const STYLE_REFERENCE_IMAGES = [traditionalSaree, traditionalMenswear, traditionalEveryday, traditionalFusion, traditionalFestival, traditionalHero]

function referenceImageFor(look, gender='neutral', salt=''){
 const text=`${look?.outfit_name||''} ${look?.category||''} ${look?.description||''} ${salt}`.toLowerCase();
 const pool=gender==='male'?[streetLook,ceremonyLook,formalLook,heroFashion]:gender==='female'?[festivalLook,formalLook,ceremonyLook,styleCollage]:STYLE_REFERENCE_IMAGES;
 let hash=0;for(let i=0;i<text.length;i++)hash=(hash*31+text.charCodeAt(i))>>>0;
 // Use the outfit name hash for a stable but varied reference. Unlike the
 // old category-only mapping, two traditional looks do not share one poster.
 return pool[hash%pool.length];
}

function paletteBackground(look){const colors=Array.isArray(look?.dress_colors)?look.dress_colors:[];return colors.length?`linear-gradient(135deg,${colors[0]?.hex||'#223b68'},${colors[1]?.hex||'#6953a6'} 58%,${colors[2]?.hex||'#cbd8ff'})`:'linear-gradient(135deg,#142d36,#246654 55%,#b69a5b)'}

function inferredGenderFor(look){const accessories=Array.isArray(look?.accessories)?look.accessories.join(' '):String(look?.accessories||'');const text=`${look?.outfit_name||''} ${look?.description||''} ${accessories}`.toLowerCase();return /watch|loafers|blazer|shirt|trouser|kurta|bandhgala|suit/.test(text)?'male':'female'}

function PaletteVisual({look}){
 const [position,setPosition]=useState({x:0,y:0});const r=look?.recommendation||{};const colors=Array.isArray(r.dress_colors)?r.dress_colors:[];const first=colors[0]?.hex||'#304c92';const second=colors[1]?.hex||'#7e68ba';const third=colors[2]?.hex||'#d7dffb';
 const move=e=>{const box=e.currentTarget.getBoundingClientRect();setPosition({x:((e.clientX-box.left)/box.width-.5)*18,y:((e.clientY-box.top)/box.height-.5)*18})};
 return <div className="palette-visual" style={{'--palette-a':first,'--palette-b':second,'--palette-c':third,'--tilt-x':`${position.x}deg`,'--tilt-y':`${position.y}deg`}} onMouseMove={move} onMouseLeave={()=>setPosition({x:0,y:0})}><div className="palette-ribbon"></div><div className="palette-orb"></div><div className="palette-lines"><i></i><i></i><i></i></div><span>HUEFIT / COLOUR STUDY</span><b>{r.category||'PERSONAL EDIT'}</b><small>MOVE TO EXPLORE</small></div>
}

function ProtectedRoute({children}) {
 const location=useLocation();
 return localStorage.getItem('huefit_token') ? children : <Navigate to="/login" replace state={{from:location.pathname}}/>
}

